const records = [];

// Get earthquake data from source
const earthquakes = $('Source 1').first().json.features || [];

// Initialize band counters and max values
let minorCount = 0, moderateCount = 0, majorCount = 0;
let minorMaxMag = -Infinity, moderateMaxMag = -Infinity, majorMaxMag = -Infinity;
let minorMaxDepth = -Infinity, moderateMaxDepth = -Infinity, majorMaxDepth = -Infinity;

// Process each earthquake
earthquakes.forEach(earthquake => {
  const mag = earthquake.properties.mag || 0;
  const depth = earthquake.geometry.coordinates[2] || 0;

  if (mag < 4.0) {
    minorCount++;
    minorMaxMag = Math.max(minorMaxMag, mag);
    minorMaxDepth = Math.max(minorMaxDepth, depth);
  } else if (mag >= 4.0 && mag <= 5.0) {
    moderateCount++;
    moderateMaxMag = Math.max(moderateMaxMag, mag);
    moderateMaxDepth = Math.max(moderateMaxDepth, depth);
  } else {
    majorCount++;
    majorMaxMag = Math.max(majorMaxMag, mag);
    majorMaxDepth = Math.max(majorMaxDepth, depth);
  }
});

// Create records for bands with events
if (minorCount > 0) {
  records.push({
    magnitude_band: 'minor',
    event_count: minorCount,
    max_magnitude: minorMaxMag,
    max_depth_km: minorMaxDepth
  });
}
if (moderateCount > 0) {
  records.push({
    magnitude_band: 'moderate',
    event_count: moderateCount,
    max_magnitude: moderateMaxMag,
    max_depth_km: moderateMaxDepth
  });
}
if (majorCount > 0) {
  records.push({
    magnitude_band: 'major',
    event_count: majorCount,
    max_magnitude: majorMaxMag,
    max_depth_km: majorMaxDepth
  });
}

return [{ json: { records } }];
